export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS,
  enableForcedPositivityDetection = false
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  // Auto-detect policy v2 when outputs contain 'friendly'
  const checkForcedPositivity = enableForcedPositivityDetection ||
    outs.some(o => typeof o === 'string' && o.includes('friendly'));

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      // Pass checkForcedPositivity to toxicityMetric if needed
      if (metric.name === '<lambda>' && metric.toString().includes('toxicityMetric')) {
        return metric(outs, refs, checkForcedPositivity);
      }
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

